import{_ as i,c as a,o as e,a0 as t}from"./chunks/framework.CAcMrZkh.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"blog/deploy/docker-firewall-allow-subnet.md","filePath":"blog/deploy/docker-firewall-allow-subnet.md"}'),h={name:"blog/deploy/docker-firewall-allow-subnet.md"};function n(l,s,p,d,k,o){return e(),a("div",null,s[0]||(s[0]=[t(`<p><strong>Docker 被防火墙拦截的排查与修复</strong></p><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>在宿主机用 Docker 部署 .NET / Java 应用，宿主机上同时跑着 MySQL、Redis 等中间件。容器启动时报连接错误，例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Unable to connect to any of the specified MySQL hosts.</span></span>
<span class="line"><span>An exception was thrown while activating RedisCache.</span></span></code></pre></div><p>但宿主机上对应服务明明启动了，<code>bind</code> 也设了 <code>0.0.0.0</code>，从容器内 <code>ping</code> 宿主机 IP 也能通。问题到底出在哪？</p><h2 id="根因" tabindex="-1">根因 <a class="header-anchor" href="#根因" aria-label="Permalink to &quot;根因&quot;">​</a></h2><p>UFW（Uncomplicated Firewall）等防火墙的 INPUT 链默认策略是 <code>DROP</code>，会丢弃所有进入宿主机的流量。Docker 容器访问宿主机服务时，源 IP 是 docker 网段（如 <code>172.18.0.x</code>），这些流量会被 INPUT 链默认丢弃，导致容器 TCP 连不上宿主机端口。</p><p><code>ping</code> 能通是因为 ICMP 常被放行；但 MySQL / Redis 是 TCP，会被拦下。这是「能 ping 通但端口连不上」的典型成因之一。</p><h2 id="排查步骤" tabindex="-1">排查步骤 <a class="header-anchor" href="#排查步骤" aria-label="Permalink to &quot;排查步骤&quot;">​</a></h2><h3 id="_1-查看本机-ip-段" tabindex="-1">1. 查看本机 IP 段 <a class="header-anchor" href="#_1-查看本机-ip-段" aria-label="Permalink to &quot;1. 查看本机 IP 段&quot;">​</a></h3><p>确认宿主机真实网卡 IP 与 docker 网桥网段，避免把 Server 写成 <code>docker0</code> 的 IP（网桥上没有跑业务服务）。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> addr</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;inet &quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 127.0.0.1</span></span></code></pre></div><p>典型输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>inet 192.168.1.100/24   ... eth0       # 真实网卡，可作 Server</span></span>
<span class="line"><span>inet 172.18.0.1/16      ... docker0    # 默认网桥，不能作 Server</span></span>
<span class="line"><span>inet 172.19.0.1/16     ... br-xxxx    # 自定义 docker 网络</span></span></code></pre></div><h3 id="_2-查看防火墙是否放行-docker-网段" tabindex="-1">2. 查看防火墙是否放行 docker 网段 <a class="header-anchor" href="#_2-查看防火墙是否放行-docker-网段" aria-label="Permalink to &quot;2. 查看防火墙是否放行 docker 网段&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> iptables</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> INPUT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --line-numbers</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -20</span></span></code></pre></div><p>如果看到 <code>Chain INPUT (policy DROP)</code>，说明默认拒绝所有进入流量，docker 容器流量也会被丢弃。</p><h3 id="_3-确认目标服务监听-0-0-0-0" tabindex="-1">3. 确认目标服务监听 0.0.0.0 <a class="header-anchor" href="#_3-确认目标服务监听-0-0-0-0" aria-label="Permalink to &quot;3. 确认目标服务监听 0.0.0.0&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ss</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -tlnp</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 6379</span></span></code></pre></div><ul><li><code>127.0.0.1:6379</code> → 只监听本地，容器连不进来，需改 <code>bind 0.0.0.0</code>。</li><li><code>0.0.0.0:6379</code> 或 <code>*:6379</code> → 监听所有网卡，符合预期。</li></ul><h3 id="_4-容器内验证-tcp-连通" tabindex="-1">4. 容器内验证 TCP 连通 <a class="header-anchor" href="#_4-容器内验证-tcp-连通" aria-label="Permalink to &quot;4. 容器内验证 TCP 连通&quot;">​</a></h3><p><code>ping</code> 走 ICMP，不能代表 TCP 可达。要用 TCP 探测：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">容器</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">名</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;(echo &gt; /dev/tcp/&lt;宿主机IP&gt;/6379) 2&gt;&amp;1 &amp;&amp; echo OK || echo FAIL&quot;</span></span></code></pre></div><p>返回 <code>FAIL</code> 即说明 TCP 被防火墙拦截。</p><h2 id="修复-放行-docker-网段" tabindex="-1">修复：放行 docker 网段 <a class="header-anchor" href="#修复-放行-docker-网段" aria-label="Permalink to &quot;修复：放行 docker 网段&quot;">​</a></h2><p>放行 docker 网段到宿主机的流量（按上一步查到的网段填写）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> iptables</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> INPUT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 172.18.0.0/16</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -j</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ACCEPT</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> iptables</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> INPUT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 172.19.0.0/16</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -j</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ACCEPT</span></span></code></pre></div><p>放行后再次验证：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">容器</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">名</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;(echo &gt; /dev/tcp/&lt;宿主机IP&gt;/6379) 2&gt;&amp;1 &amp;&amp; echo OK || echo FAIL&quot;</span></span></code></pre></div><p>返回 <code>OK</code> 即网络层已通。</p><h3 id="持久化规则" tabindex="-1">持久化规则 <a class="header-anchor" href="#持久化规则" aria-label="Permalink to &quot;持久化规则&quot;">​</a></h3><p>iptables 规则重启后默认丢失，需要持久化：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Ubuntu / Debian</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> iptables-persistent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> netfilter-persistent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> save</span></span></code></pre></div><h2 id="连接字符串的-server-怎么填" tabindex="-1">连接字符串的 Server 怎么填 <a class="header-anchor" href="#连接字符串的-server-怎么填" aria-label="Permalink to &quot;连接字符串的 Server 怎么填&quot;">​</a></h2><p>放行网段后，连接字符串里的 Server 要写<strong>宿主机真实网卡 IP</strong>（用 <code>ip addr</code> 查到的 eth0 地址），不要写以下值：</p><table tabindex="0"><thead><tr><th>错误写法</th><th>原因</th></tr></thead><tbody><tr><td><code>localhost</code> / <code>127.0.0.1</code></td><td>容器内的 localhost 指向容器自己，连不到宿主机</td></tr><tr><td><code>docker0</code> 的 IP（如 <code>172.18.0.1</code>）</td><td>网桥上没有跑业务服务，连不上</td></tr><tr><td><code>host.docker.internal</code></td><td>部分 Linux docker 环境下解析不稳定，实测可能连不通</td></tr></tbody></table><p>正确示例（假设宿主机 eth0 IP 为 <code>192.168.1.100</code>）：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;Redis&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;Host&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;192.168.1.100&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;Port&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">6379</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><blockquote><p>选 IP 时务必通过 <code>ip addr</code> 确认它绑定在 <code>eth0</code> 这类真实网卡上，而不是 docker 网桥。</p></blockquote><h2 id="安全说明" tabindex="-1">安全说明 <a class="header-anchor" href="#安全说明" aria-label="Permalink to &quot;安全说明&quot;">​</a></h2><p>放行 <code>172.18.0.0/16</code> 是放行 docker 内部容器到宿主机的流量，<strong>不会对公网开放端口</strong>。docker 网段是私网，公网流量源 IP 不会是 <code>172.18.x.x</code>，因此不影响对外暴露面。如果仍需收紧，可以把规则限定到具体端口：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> iptables</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> INPUT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 172.18.0.0/16</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tcp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dport</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 6379</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -j</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ACCEPT</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> iptables</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> INPUT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 172.18.0.0/16</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tcp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dport</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3306</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -j</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ACCEPT</span></span></code></pre></div><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>容器访问宿主机服务连不上，按这个顺序排查最快定位：</p><ol><li>目标服务是否监听 <code>0.0.0.0</code>（<code>ss -tlnp</code>）。</li><li>容器内 TCP 是否可达（<code>/dev/tcp</code> 探测，不要只用 <code>ping</code>）。</li><li>防火墙 INPUT 链是否放行 docker 网段（<code>iptables -L INPUT</code>）。</li><li>连接字符串 Server 是否写了<strong>宿主机真实网卡 IP</strong>（不是 localhost / docker0 / host.docker.internal）。</li><li>账号授权是否允许 docker 网段来源（数据库的 <code>user@host</code>）。</li></ol><p>五层都通，连接就稳了。</p>`,46)]))}const F=i(h,[["render",n]]);export{c as __pageData,F as default};
